Q: Python polars script leaks memory and crashes (scans CSV to lazyframes - writes to database) A: <p>The problem is parsing the CSV with schema inference when the line separator is &quot;\r&quot; (this is apparently a bug in Polars). The file has also quoting problems, with quoted titles inside unquoted fields.</p>
<p>Here is an attempt to clean the file, in C. On this specific file there is no error remaining.</p>
<p>Basically:</p>
<ul>
<li><p>Check for quotes at field boundary (around separator and at beginning and end of line)</p>
</li>
<li><p>All other quotes are treated as normal characters. Field separators in a quoted field are normal characters as well</p>
</li>
</ul>
<p>However, with only this rule there were still 13 errors, with fields starting with a title (hence a &quot; that is not a true field quote). To fix this, only accept such a quote as the beginning of a quoted field if there is a plausible end of quoted field ahead on the line. This can still fail in some circumstances (if a badly quoted field is followed by a correctly quoted field), but here it's enough to fix the 13 remaining rows.</p>
<p>On output, all fields are quoted, and all quotes inside fields are duplicated (I assume they are never duplicated in the input file, even though they should). And line separators are '\n' as expected by Polars. Polars can import the result.</p>
<p>The input file is read in 64K blocks, and handled line by line, and the output file is written line by line.</p>
<p>Usage:</p>
<pre><code>% gcc -O2 -Wall -Wextra -Wconversion -std=c11 -pedantic filter.c -o filter
% time ./filter BroadcastLogs_2016_Q1_M1.csv out.csv                 

Output:

File BroadcastLogs_2016_Q1_M1.csv
6499106 rows 30 columns
0 rows with bad column count, 0 rows with bad quotes

./filter BroadcastLogs_2016_Q1_M1.csv out.csv  2.93s user 3.00s system 91% cpu 6.510 total
</code></pre>
<p>I checked this on Linux, but the program should run on Windows, I don't use anything besides standard C. The 'time' command is not mandatory, it's only here to check execution time, and it's 6.5 seconds on my laptop (which has a Zen 2 CPU).</p>
<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

typedef struct {
    size_t capacity;
    size_t size;
    char *data;
} string_t;

typedef enum {
    VALIDATE_OK = 0,
    VALIDATE_ERROR_QUOTE = 1,
    VALIDATE_ERROR_ALLOC = -1
} validate_result_t;

#define APPEND_OR_FAIL(buf, ch) \
    do { if (append((buf), (ch)) != 0) return VALIDATE_ERROR_ALLOC; } while (0)

int append(string_t *str, char c) {
    if (str-&gt;size == str-&gt;capacity) {
        size_t new_capacity = str-&gt;capacity == 0 ? 1 : str-&gt;capacity * 2;
        char *ptr = realloc(str-&gt;data, new_capacity);
        if (ptr == NULL) {
            return -1;
        } else {
            str-&gt;data = ptr;
            str-&gt;capacity = new_capacity;
        }
    }

    str-&gt;data[str-&gt;size++] = c;
    return 0;
}

string_t *alloc_string(void) {
    string_t *ptr = malloc(sizeof(string_t));
    if (ptr) {
        ptr-&gt;data = NULL;
        ptr-&gt;capacity = ptr-&gt;size = 0;
    }
    return ptr;
}

void free_string(string_t *ptr) {
    if (ptr != NULL) {
        free(ptr-&gt;data);
        free(ptr);
    }
}

validate_result_t validate(string_t *input_line, string_t *output_line, size_t *ncol_cur, char sep, char quote) {
    int is_quoted_field, end_of_field;
    size_t ncol = 0;
    size_t n = input_line-&gt;size;
    char *s = input_line-&gt;data;
    output_line-&gt;size = 0;
    validate_result_t result = VALIDATE_OK; // success by default

    for (size_t j = 0; j &lt; n; ) {
        // beginning of a field
        ncol++;

        if (s[j] == quote) {
            // only accept this field as quoted if there is a plausible quoted end of field ahead
            int is_valid = 0;
            for (size_t k = j+1; k &lt; n; k++) {
                if (s[k] == quote &amp;&amp; (k+1 == n || s[k+1] == sep)) {
                    is_valid = 1;
                    break;
                }
            }

            if (is_valid) {
                is_quoted_field = 1;
                j++;
            } else {
                is_quoted_field = 0;
            }
        } else {
            is_quoted_field = 0;
        }

        APPEND_OR_FAIL(output_line, quote);
        end_of_field = 0;

        while (j &lt; n) {
            char c = s[j];
            if (c == sep) {
                if (is_quoted_field) {
                    // quoted field: a field separator not preceded by a quote is part of the field
                    APPEND_OR_FAIL(output_line, c);
                    j++;
                } else {
                    // unquoted field: a field separator is the end of the field, but we force quotes on output
                    APPEND_OR_FAIL(output_line, quote);
                    APPEND_OR_FAIL(output_line, c);
                    j++;
                    end_of_field = 1;
                    break;
                }
            } else if (c == quote) {
                if (!is_quoted_field) {
                    // a quote in the middle of a field is considered to be part of the field, and must be double-quoted
                    // assumption: the input file doesn't double-quote these characters (which is an error)
                    APPEND_OR_FAIL(output_line, c);
                    APPEND_OR_FAIL(output_line, c);
                    j++;
                } else if (j+1 == n) {
                    // a quote at the end of the line (hence the end of the field) of a quoted field, is only written once
                    APPEND_OR_FAIL(output_line, c);
                    j++;
                    // no dangling separator, flag this to avoid adding an empty field
                    end_of_field = 2;
                    break;
                } else if (s[j+1] == sep) {
                    // a quote followed by the field separator marks the end of the field
                    APPEND_OR_FAIL(output_line, quote);
                    APPEND_OR_FAIL(output_line, sep);
                    j += 2;
                    end_of_field = 1;
                    break;
                } else {
                    APPEND_OR_FAIL(output_line, c);
                    APPEND_OR_FAIL(output_line, c);
                    j++;
                }
            } else {
                // not a separator nor a quote, hence part of the field
                APPEND_OR_FAIL(output_line, c);
                j++;
            }
        }

        if (j == n) {
            switch (end_of_field) {
            case 0:
                if(is_quoted_field) {
                    // this is not supposed to happen: the last field of the line is quoted but has no end quote
                    result = VALIDATE_ERROR_QUOTE;
                }

                // either way, we must add a quote as all fields are quoted on output
                APPEND_OR_FAIL(output_line, quote);
                break;
            case 1:
                // a field separator exactly at the end of line must be followed by an empty field
                APPEND_OR_FAIL(output_line, quote);
                APPEND_OR_FAIL(output_line, quote);
                ncol++;
                break;
            default: // must be 2
                break;
            }
        }

    }

    // add line separator
    APPEND_OR_FAIL(output_line, '\n');
    *ncol_cur = ncol;
    return result;
}

int main(int argc, char **argv) {
    // buffer to read file blocks
    char *buffer = NULL;
    size_t buflen = 65536;

    // number of characters to process in the current block
    size_t nchar; 

    // input and output files
    FILE *fin = NULL, *fout = NULL;

    // input and output line
    string_t *input_line = NULL, *output_line = NULL;

    // status initially set to FAILURE in case an error occurs
    int status = EXIT_FAILURE;

    // number of rows and columns of the CSV file
    // the number of columns will be checked
    size_t nrow = 0, ncol = 0;

    // number of columns of the current row
    size_t ncol_cur;

    // result of line validation
    validate_result_t result;

    // number of rows with a bad number of columns
    size_t nrow_err_col = 0;

    // number of rows with a quote error
    size_t nrow_err_quote = 0;

    // characters used as line separator (eol), field separator (sep), and quote
    char eol = '\r', sep = '|', quote = '&quot;';

    // skip bad rows ?
    int skip_on_error = 0;

    // print bad rows ?
    int print_errors = 1;

    if (argc != 3) {
        fprintf(stderr, &quot;filter infile outfile\n&quot;);
        goto Epilogue;
    }

    char *infile = argv[1];
    char *outfile = argv[2];

    fin = fopen(infile, &quot;rb&quot;);
    if (fin == NULL) {
        fprintf(stderr, &quot;Error: Unable to open file %s\n&quot;, infile);
        goto Epilogue;
    }

    fout = fopen(outfile, &quot;wb&quot;);
    if (fout == NULL) {
        fprintf(stderr, &quot;Error: Unable to open file %s\n&quot;, outfile);
        goto Epilogue;
    }

    buffer = malloc(buflen);
    if (buffer == NULL) {
        fprintf(stderr, &quot;Error: Unable to allocate memory for the buffer\n&quot;);
        goto Epilogue;
    }

    if ((input_line = alloc_string()) == NULL) {
        fprintf(stderr, &quot;Error: Unable to allocate memory for the input line\n&quot;);
        goto Epilogue;
    }

    if ((output_line = alloc_string()) == NULL) {
        fprintf(stderr, &quot;Error: Unable to allocate memory for the output line\n&quot;);
        goto Epilogue;
    }

    while ((nchar = fread(buffer, 1, buflen, fin)) &gt; 0) {
        for (size_t i = 0; i &lt; nchar; i++) {
            char c = buffer[i];
            if (c == eol) {
                result = validate(input_line, output_line, &amp;ncol_cur, sep, quote);
                if (result &lt; 0) {
                    fprintf(stderr, &quot;Error: Unable to extend output line\n&quot;);
                    goto Epilogue;
                }

                if (result != 0) {
                    nrow_err_quote++;
                }

                if (nrow == 0) {
                    ncol = ncol_cur;
                } else {
                    if (ncol != ncol_cur) {
                        nrow_err_col++;
                    }
                }

                if (print_errors &amp;&amp; (result != 0 || (nrow &gt; 0 &amp;&amp; ncol != ncol_cur))) {
                    if (append(input_line, 0) != 0) {
                        fprintf(stderr, &quot;Error: Unable to extend input line\n&quot;);
                        goto Epilogue;
                    }

                    printf(&quot;Row[%zu] (ncol=%zu) %s\n&quot;, nrow, ncol_cur, input_line-&gt;data);
                }

                if ((result == 0 &amp;&amp; (nrow == 0 || ncol == ncol_cur)) || !skip_on_error) {
                    if (fwrite(output_line-&gt;data, 1, output_line-&gt;size, fout) != output_line-&gt;size) {
                        fprintf(stderr, &quot;Unable to write file\n&quot;);
                        goto Epilogue;
                    }
                }

                nrow++;

                // reset the input line size to start a new line
                input_line-&gt;size = 0;
            } else {
                if (append(input_line, c) != 0) {
                    fprintf(stderr, &quot;Unable to extend input line\n&quot;);
                    goto Epilogue;
                }
            }
        }
    }

    if (ferror(fin) || !feof(fin)) {
        fprintf(stderr, &quot;Error: read failure on %s\n&quot;, infile);
        goto Epilogue;
    }

    if (input_line-&gt;size != 0) {
        fprintf(stderr, &quot;Warning: no EOL character at end of line.\n&quot;);

        result = validate(input_line, output_line, &amp;ncol_cur, sep, quote);
        if (result &lt; 0) {
            fprintf(stderr, &quot;Error: unable to extend output line\n&quot;);
            goto Epilogue;
        }

        if (result != 0) {
            nrow_err_quote++;
        }

        if (nrow == 0) {
            ncol = ncol_cur;
        } else {
            if (ncol != ncol_cur) {
                nrow_err_col++;
            }
        }

        if (print_errors &amp;&amp; (result != 0 || (nrow &gt; 0 &amp;&amp; ncol != ncol_cur))) {
            if (append(input_line, 0) != 0) {
                fprintf(stderr, &quot;Error: Unable to extend input line\n&quot;);
                goto Epilogue;
            }

            printf(&quot;Row[%zu] (ncol=%zu) %s\n&quot;, nrow, ncol_cur, input_line-&gt;data);
        }

        if ((result == 0 &amp;&amp; (nrow == 0 || ncol == ncol_cur)) || !skip_on_error) {
            if (fwrite(output_line-&gt;data, 1, output_line-&gt;size, fout) != output_line-&gt;size) {
                fprintf(stderr, &quot;Unable to write file\n&quot;);
                goto Epilogue;
            }
        }

        nrow++;
    }

    printf(&quot;File %s\n&quot;, infile);
    printf(&quot;%zu rows %zu columns\n&quot;, nrow, ncol);
    printf(&quot;%zu rows with bad column count, %zu rows with bad quotes\n&quot;, nrow_err_col, nrow_err_quote);

    status = EXIT_SUCCESS;
Epilogue:
    if (fin) fclose(fin);
    if (fout) fclose(fout);
    free(buffer);
    free_string(input_line);
    free_string(output_line);
    return status;    
}
</code></pre>

Q: How do i get data from a txt file and send it to Excel spreadsheet?(I only want everything after the &quot;:&quot; in the txt file)? A: <p>If your file <code>email.txt</code> Always has the format you said:</p>

<pre><code>Name: John
phone: (xxx) xxx-xxxx
</code></pre>

<p>I'm not familiarized with the row and cell creation, so I will give you some pseudo code to you understand what you have to do on your code:</p>

<p>On this part of your code:</p>

<pre><code>//create a count for rows here
inr rowNumber = 0;
//Here you are reading your list with all data readed
for(int i=0;i&lt;arr.size()-1;i+=2){ //the -1 is for the array to stop on the 
                                 //last but one row

    row = spreadSheet.createRow((short) rowNumber); //external count

    //pseudocode from here
    cell1 = row.createCell(0); 
    cell2 = row.createCell(1); 

    cell1.setCellValue(  arr.get(i).substring(arr.get(i).indexOf(":")+1) );
                              // ^ this is for name
    cell2.setCellValue(  arr.get(i+1).substring(arr.get(i+1).indexOf(":")+1) );
                               // ^ this is for phone

    rowNumber++; //increment your rowNumber
}
</code></pre>
